def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

If extract_spec_version is True then will look at the type value to determine
the specification version. In the case that there is no type value or it isn't
valid, then other tests will be based on the version given in self.spec_version.
    """
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    self.inventory = inventory

    # --- type / spec version ---
    if 'type' not in inventory:
        self.error('E036d')
    elif not isinstance(inventory['type'], str):
        self.error('E038a')
    else:
        m = re.match(r'^https?://ocfl\.io/(\d+\.\d+)/spec/#inventory$', inventory['type'])
        if extract_spec_version:
            if not m:
                self.error('E038b')
            else:
                found_version = m.group(1)
                if found_version not in self.spec_versions_supported:
                    self.error('E038c')
                else:
                    self.spec_version = found_version
        else:
            if not m:
                self.error('E038a')
            else:
                found_version = m.group(1)
                if found_version not in self.spec_versions_supported:
                    self.error('E038a')

    # --- id ---
    if 'id' not in inventory:
        self.error('E036a')
    elif not isinstance(inventory['id'], str):
        self.error('E037a')
    else:
        self.id = inventory['id']
        if not re.match(r'^[a-zA-Z][a-zA-Z0-9+.-]*:', self.id):
            self.warning('W005')
        if not re.match(r'^[a-zA-Z][a-zA-Z0-9+.-]*:[^\s]+$', self.id):
            self.warning('W004')

    # --- digestAlgorithm ---
    if 'digestAlgorithm' not in inventory:
        self.error('E036b')
    elif not isinstance(inventory['digestAlgorithm'], str):
        self.error('E037b')
    else:
        self.digest_algorithm = inventory['digestAlgorithm']
        if not self.lax_digests:
            if self.digest_algorithm not in ('sha512', 'sha256'):
                self.error('E039')

    # --- head ---
    if 'head' not in inventory:
        self.error('E036c')
    elif not isinstance(inventory['head'], str):
        self.error('E040')
    else:
        self.head = inventory['head']

    # --- contentDirectory ---
    if 'contentDirectory' in inventory:
        cd = inventory['contentDirectory']
        if not isinstance(cd, str):
            self.error('E017')
        elif cd == '' or cd.startswith('/') or cd.endswith('/') or '//' in cd:
            self.error('E017')
        elif cd == '..' or cd.startswith('../') or cd.endswith('/..') or '/../' in cd or cd == '.':
            self.error('E018')
        else:
            self.content_directory = cd
    else:
        self.content_directory = 'content'

    # --- manifest ---
    if 'manifest' not in inventory:
        self.error('E041a')
        manifest_files = {}
        unnormalized_digests = set()
    else:
        (manifest_files, _, unnormalized_digests) = self.validate_manifest(inventory['manifest'])
    self.manifest_files = manifest_files
    self.unnormalized_digests = unnormalized_digests

    # --- versions ---
    if 'versions' not in inventory:
        self.error('E041b')
        all_versions = []
    else:
        all_versions = self.validate_versions(inventory['versions'], [], unnormalized_digests)
    self.all_versions = all_versions

    # --- fixity ---
    if 'fixity' in inventory:
        self.validate_fixity(inventory['fixity'], manifest_files)

    # --- cross checks ---
    if manifest_files and all_versions:
        self.check_content_paths_map_to_versions(manifest_files, all_versions)

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

The input variable prior is also expected to be an InventoryValidator object
and both self and prior inventories are assumed to have been checked for
internal consistency.
    """
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Prior must have fewer versions than self
    if len(prior.all_versions) >= len(self.all_versions):
        self.error('E066a', prior_versions=prior.all_versions,
                   versions=self.all_versions)
        return

    # Prior versions must be a prefix of self versions
    for i, version in enumerate(prior.all_versions):
        if i >= len(self.all_versions) or self.all_versions[i] != version:
            self.error('E066a', prior_versions=prior.all_versions,
                       versions=self.all_versions)
            return

    # Compare each version's state and manifest locations
    for version in prior.all_versions:
        self.compare_states_for_version(prior, version)

        prior_state = prior.inventory['versions'][version]['state']
        self_state = self.inventory['versions'][version]['state']

        prior_paths = {}
        for digest, paths in prior_state.items():
            for path in paths:
                prior_paths[path] = digest
        self_paths = {}
        for digest, paths in self_state.items():
            for path in paths:
                self_paths[path] = digest

        for path in prior_paths:
            if path not in self_paths:
                continue
            prior_digest = prior_paths[path]
            self_digest = self_paths[path]
            prior_locs = prior.inventory['manifest'].get(prior_digest, [])
            self_locs = self.inventory['manifest'].get(self_digest, [])
            prior_content = set()
            for loc in prior_locs:
                parts = loc.split('/', 1)
                if len(parts) == 2:
                    prior_content.add(parts[1])
            self_content = set()
            for loc in self_locs:
                parts = loc.split('/', 1)
                if len(parts) == 2:
                    self_content.add(parts[1])
            if prior_content != self_content:
                self.error('E066c', version=version, path=path,
                           prior_locations=prior_locs,
                           locations=self_locs)

def validate_fixity(self, fixity, manifest_files):
    """
    Validate fixity block in inventory.

Check the structure of the fixity block and makes sure that only files
listed in the manifest are referenced.
    """
    """
    Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        self.error('E056a')
        return
    for algorithm in fixity:
        regex = None
        if not self.lax_digests:
            try:
                regex = digest_regex(algorithm)
            except Exception:
                regex = None
            if regex is None:
                self.error('E056b', algorithm=algorithm)
                continue
        if not isinstance(fixity[algorithm], dict):
            self.error('E057a', algorithm=algorithm)
            continue
        digests_seen = set()
        for digest in fixity[algorithm]:
            if not self.lax_digests:
                if not re.match(regex, digest):
                    self.error('E057b', algorithm=algorithm, digest=digest)
                    continue
            if not isinstance(fixity[algorithm][digest], list):
                self.error('E057c', algorithm=algorithm, digest=digest)
                continue
            try:
                norm_digest = normalized_digest(digest, digest_type=algorithm)
            except Exception:
                norm_digest = digest
            if norm_digest in digests_seen:
                self.error('E097', algorithm=algorithm, digest=digest)
            else:
                digests_seen.add(norm_digest)
            for filepath in fixity[algorithm][digest]:
                if manifest_files is not None and filepath not in manifest_files:
                    self.error('E057d', algorithm=algorithm, digest=digest, filepath=filepath)

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

Also keep a record of any content digests different from those in the root inventory
so that we can also check them when validating the content.

version_dirs is an array of version directory names and is assumed to be in
version sequence (1, 2, 3...).
    """
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    prior_manifest_digests = {}
    prior_fixity_digests = {}

    # Get root inventory manifest and fixity for comparison
    root_manifest = {}
    root_fixity = {}
    if self.root_inv_validator is not None:
        root_inv = self.root_inv_validator.inventory
        root_manifest = root_inv.get('manifest', {})
        root_fixity = root_inv.get('fixity', {})

    for version_dir in version_dirs:
        inv_path = version_dir + '/inventory.json'

        # Each version SHOULD have an inventory
        if not self.obj_fs.exists(inv_path):
            self.log.error('E064', version=version_dir)
            continue

        # Validate the version inventory
        try:
            inventory, inv_validator = self.validate_inventory(
                inv_path,
                where=version_dir,
                extract_spec_version=False
            )
        except ValidatorAbortException:
            continue

        # Check version inventory head matches directory
        if inv_validator.head != version_dir:
            self.log.error('E065', version=version_dir, head=inv_validator.head)

        # Check id matches root
        if inv_validator.id != self.id:
            self.log.error('E066', version=version_dir,
                          expected=self.id, found=inv_validator.id)

        # Check digest algorithm matches root
        if inv_validator.digest_algorithm != self.digest_algorithm:
            self.log.error('E067', version=version_dir,
                          expected=self.digest_algorithm,
                          found=inv_validator.digest_algorithm)

        # Validate inventory digest file
        self.validate_inventory_digest(inv_path, inv_validator.digest_algorithm,
                                       where=version_dir)

        # Record manifest digests not in root inventory
        # Structure: {version: {digest: [paths]}}
        manifest = inventory.get('manifest', {})
        for digest, paths in manifest.items():
            if digest not in root_manifest:
                if version_dir not in prior_manifest_digests:
                    prior_manifest_digests[version_dir] = {}
                prior_manifest_digests[version_dir][digest] = paths

        # Record fixity digests not in root inventory
        # Structure: {version: {algorithm: {digest: [paths]}}}
        fixity = inventory.get('fixity', {})
        for algorithm, digests in fixity.items():
            for digest, paths in digests.items():
                root_algo_digests = root_fixity.get(algorithm, {})
                if digest not in root_algo_digests:
                    if version_dir not in prior_fixity_digests:
                        prior_fixity_digests[version_dir] = {}
                    if algorithm not in prior_fixity_digests[version_dir]:
                        prior_fixity_digests[version_dir][algorithm] = {}
                    prior_fixity_digests[version_dir][algorithm][digest] = paths

    return (prior_manifest_digests, prior_fixity_digests)

