def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

By default all the values are strings.

:param parser_name: The command name, e.g. main, virsh, ospd, etc
:param values_dict: The dict of with arguments
    """
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Get the parser option specs for this parser
    parser_specs = self.spec_helper.get_parser_option_specs(parser_name)

    if not parser_specs:
        return

    # Build a lookup dict for specs by name
    specs_by_name = {}
    for spec in parser_specs:
        if 'name' in spec:
            specs_by_name[spec['name']] = spec

    for arg_name, arg_value in values_dict.items():
        arg_spec = specs_by_name.get(arg_name)
        if not arg_spec:
            continue

        arg_type = arg_spec.get('type', str)
        action = arg_spec.get('action', '')

        # Handle boolean actions
        if action in ('store_true', 'store_false'):
            if isinstance(arg_value, str):
                values_dict[arg_name] = arg_value.lower() in ('true', 'yes', '1', 'on')
            continue

        # Handle list/append actions
        if action == 'append' or arg_type == list:
            if isinstance(arg_value, str):
                values_dict[arg_name] = [v.strip() for v in arg_value.split(',')]
            continue

        # Handle complex types
        if arg_type in COMPLEX_TYPES:
            if isinstance(arg_value, str):
                try:
                    values_dict[arg_name] = yaml.safe_load(arg_value)
                except yaml.YAMLError:
                    pass
            continue

        # Handle basic types
        if arg_type in (int, float, bool):
            if isinstance(arg_value, str):
                try:
                    if arg_type == bool:
                        values_dict[arg_name] = arg_value.lower() in ('true', 'yes', '1', 'on')
                    else:
                        values_dict[arg_name] = arg_type(arg_value)
                except (ValueError, TypeError):
                    pass

def identify_request(request: RequestType):
    """
    Try to identify whether this is a Diaspora request.

Try first public message. Then private message. The check if this is a legacy payload.
    """
    """
    Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    body = decode_if_bytes(request.body)

    # Try to identify as a public MagicEnvelope payload
    try:
        env = MagicEnvelope(payload=body)
        if env.doc is not None:
            return True
    except Exception:
        pass

    # Try to identify as an encrypted payload
    try:
        encrypted = EncryptedPayload(body)
        if encrypted.header:
            return True
    except Exception:
        pass

    # Try to identify as a legacy payload (reshare, etc.)
    try:
        doc = etree.fromstring(encode_if_text(body))
        if doc.tag in ("status_message", "reshare", "retraction", "signed_retraction", "profile", "comment"):
            return True
    except Exception:
        pass

    return False

